def _install_pandas_scalar_shim() -> str | None:
    """Restore the scalar coercion the authors' hyper-parameter reader relies on.

    ``utils.set_best_train_args`` does ``float(table['lr'][ind])`` where ``ind``
    is a length-1 integer array, i.e. it coerces a length-1 ``pandas.Series`` to
    a Python scalar.  pandas >= 1.0 dropped ``Series.__float__``/``__int__``, so
    that coercion now raises ``TypeError``.  We only restore the exact old
    behaviour for length-1 numeric Series (the value read from
    FEGNN_params.csv is unchanged); anything else still raises.
    """
    import pandas as pd

    changed = []
    if not hasattr(pd.Series, "__float__"):
        def __float__(self) -> float:
            if len(self) == 1:
                return float(self.iloc[0])
            raise TypeError("cannot convert a non-length-1 Series to float")

        pd.Series.__float__ = __float__
        changed.append("pandas.Series.__float__")
    if not hasattr(pd.Series, "__int__"):
        def __int__(self) -> int:
            if len(self) == 1:
                return int(self.iloc[0])
            raise TypeError("cannot convert a non-length-1 Series to int")

        pd.Series.__int__ = __int__
        changed.append("pandas.Series.__int__")
    return ", ".join(changed) if changed else None


